<?php
/** NexaBiz source patch. Self-contained; no network or composer dependency. */
if (PHP_SAPI !== 'cli') { http_response_code(403); exit('CLI only'); }
$command=$argv[1]??'--help';
if (!in_array($command,['--dry-run','--apply','--rollback','--help'],true)) {fwrite(STDERR,"Invalid command.\n");exit(2);}
$root=__DIR__;
if (!is_file($root.'/artisan') || !is_file($root.'/composer.json')) {fwrite(STDERR,"Place this patch in the Laravel root next to artisan and composer.json.\n");exit(2);}
$backupRoot=$root.'/storage/app/nexabiz-patch-backups/2026-11-23-business-ecommerce';
$stateFile=$backupRoot.'/state.json';
function say($message){echo $message,"\n";}
function stop($message,$code=1){fwrite(STDERR,$message."\n");exit($code);}
function digest($file){return is_file($file)?hash_file('sha256',$file):null;}
function saveFile($file,$data){
 $dir=dirname($file);if (!is_dir($dir) && !mkdir($dir,0775,true) && !is_dir($dir))throw new RuntimeException('Cannot create '.$dir);
 $tmp=$file.'.nexabiztmp';if(file_put_contents($tmp,$data,LOCK_EX)===false)throw new RuntimeException('Cannot write '.$tmp);
 if (!rename($tmp,$file)){@unlink($tmp);throw new RuntimeException('Cannot replace '.$file);}
}
if($command==='--help'){say('Usage: php '.basename(__FILE__).' --dry-run | --apply | --rollback');exit(0);}
if($command==='--rollback'){
 if(!is_file($stateFile))stop('No applied patch backup was found.');
 $state=json_decode(file_get_contents($stateFile),true,512,JSON_THROW_ON_ERROR);
 $conflicts=[];
 foreach($state['entries'] as $name=>$record){
  $current=digest($root.'/'.$name);
  if($current!==($record['installed']??null))$conflicts[]=$name;
 }
 if($conflicts)stop("Cannot safely roll back edited files:\n - ".implode("\n - ",$conflicts));
 foreach($state['entries'] as $name=>$record){
  $path=$root.'/'.$name;
  if($record['previous']===null){if(is_file($path))unlink($path);}
  else saveFile($path,file_get_contents($backupRoot.'/files/'.$name));
  say('RESTORED '.$name);
 }
 @unlink($stateFile);say('Rollback complete. Database schema and uploaded media were not changed.');exit(0);
}
if(is_file($stateFile))stop('Patch was already applied. Use --rollback before re-applying or keep current files.');
$encoded=trim(substr(file_get_contents(__FILE__),__COMPILER_HALT_OFFSET__));
$decoded=base64_decode($encoded,true);
if($decoded===false)stop('Patch payload is corrupt.');
$plain=gzuncompress($decoded);
if($plain===false)stop('Patch payload cannot be decompressed.');
$payload=json_decode($plain,true,512,JSON_THROW_ON_ERROR);
$changes=[];$unchanged=[];$conflicts=[];
foreach($payload['entries'] as $name=>$entry){
 if(!preg_match('~^(app/|routes/|database/|resources/|public/|NEXABIZ_PATCH_NOTES\.md$)~',$name) || str_contains($name,'..') || str_contains($name,'\\'))stop('Unsafe patch path: '.$name);
 $path=$root.'/'.$name;
 $current=digest($path);
 if($current===$entry['new']){$unchanged[]=$name;continue;}
 if($current!==$entry['old']){$conflicts[]=$name;continue;}
 $changes[$name]=$entry;
}
say('NexaBiz patch '.$payload['version'].': '.count($changes).' changes; '.count($unchanged).' already current; '.count($conflicts).' conflicts');
if($conflicts){say('Conflicts (unchanged, for safety):');foreach($conflicts as $name)say('  ! '.$name);stop('Files do not match the supplied app(9).zip snapshot. Nothing was applied.');}
if($command==='--dry-run'){foreach($changes as $name=>$entry)say('  '.($entry['old']===null?'ADD':($entry['new']===null?'REMOVE':'UPDATE')).' '.$name);exit(0);}
if(!$changes){say('Already up-to-date.');exit(0);}
$restore=[];
foreach($changes as $name=>$entry){
 $oldFile=$root.'/'.$name;
 $restore[$name]=['previous'=>$entry['old'],'installed'=>$entry['new']];
 if($entry['old']!==null){
  $backup=$backupRoot.'/files/'.$name;
  $dir=dirname($backup);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))stop('Unable to create backup directory.');
  if(!copy($oldFile,$backup))stop('Failed to back up '.$name);
 }
}
try{
 foreach($changes as $name=>$entry){
  $path=$root.'/'.$name;
  if($entry['new']===null){if(is_file($path)&&!unlink($path))throw new RuntimeException('Cannot remove '.$name);}
  else{
   $data=base64_decode($entry['data'],true);
   if($data===false||hash('sha256',$data)!==$entry['new'])throw new RuntimeException('Invalid bytes for '.$name);
   saveFile($path,$data);
  }
  say('OK '.$name);
 }
 if(!is_dir($backupRoot) && !mkdir($backupRoot,0775,true) && !is_dir($backupRoot))throw new RuntimeException('Cannot create backup root.');
 saveFile($stateFile,json_encode(['version'=>$payload['version'],'entries'=>$restore],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
 say('Patch applied successfully. Backups in storage/app/nexabiz-patch-backups/.');
}catch(Throwable $e){
 fwrite(STDERR,'Apply failed: '.$e->getMessage()."\nReverting file changes.\n");
 foreach($restore as $name=>$record){$path=$root.'/'.$name;if($record['previous']===null){if(is_file($path))@unlink($path);}else{$backup=$backupRoot.'/files/'.$name;if(is_file($backup))saveFile($path,file_get_contents($backup));}}
 exit(1);
}
__halt_compiler();

